#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>

int orderOfLargestPlusSign(int n, int** mines, int minesSize, int* minesColSize) {
    (void)minesColSize;

    unsigned char* blocked = calloc((size_t)n * n, sizeof(unsigned char));
    int* dp = calloc((size_t)n * n, sizeof(int));
    if (!blocked || !dp) {
        free(blocked);
        free(dp);
        return 0;
    }

    for (int i = 0; i < minesSize; ++i) {
        int r = mines[i][0], c = mines[i][1];
        blocked[(size_t)r * n + c] = 1;
    }

    int ans = 0;
    for (int r = 0; r < n; ++r) {
        int run = 0;
        for (int c = 0; c < n; ++c) {
            run = blocked[(size_t)r * n + c] ? 0 : run + 1;
            dp[(size_t)r * n + c] = run;
        }
        run = 0;
        for (int c = n - 1; c >= 0; --c) {
            run = blocked[(size_t)r * n + c] ? 0 : run + 1;
            int idx = r * n + c;
            if (run < dp[idx]) dp[idx] = run;
        }
    }

    for (int c = 0; c < n; ++c) {
        int run = 0;
        for (int r = 0; r < n; ++r) {
            run = blocked[(size_t)r * n + c] ? 0 : run + 1;
            int idx = r * n + c;
            if (run < dp[idx]) dp[idx] = run;
        }
        run = 0;
        for (int r = n - 1; r >= 0; --r) {
            run = blocked[(size_t)r * n + c] ? 0 : run + 1;
            int idx = r * n + c;
            if (run < dp[idx]) dp[idx] = run;
            if (dp[idx] > ans) ans = dp[idx];
        }
    }

    free(blocked);
    free(dp);
    return ans;
}

