        for (const auto& mine : mines) {
            blocked[mine[0]][mine[1]] = 1;
        }

        vector<vector<int>> dp(n, vector<int>(n, 0));
        int ans = 0;

        for (int r = 0; r < n; ++r) {
            int run = 0;
            for (int c = 0; c < n; ++c) {
                run = blocked[r][c] ? 0 : run + 1;
                dp[r][c] = run;
            }
            run = 0;
            for (int c = n - 1; c >= 0; --c) {
                run = blocked[r][c] ? 0 : run + 1;
                dp[r][c] = min(dp[r][c], run);
            }
        }

        for (int c = 0; c < n; ++c) {
            int run = 0;
            for (int r = 0; r < n; ++r) {
